selector_to_html = {"a[href=\"#id7\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u670d\u52a1<a class=\"headerlink\" href=\"#id7\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u7528\u6237\u6307\u5357<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u672c\u6307\u5357\u4ecb\u7ecd\u5982\u4f55\u914d\u7f6e FlagScale \u4ee5\u53ca\u5982\u4f55\u8fd0\u884c\u8bad\u7ec3\u3001\u63a8\u7406\u3001\u670d\u52a1\u548c\u5f3a\u5316\u5b66\u4e60\u4efb\u52a1\u3002</p>", "a[href=\"multi-platform-training.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u591a\u5e73\u53f0\u8bad\u7ec3\u4e0e\u6d4b\u8bd5<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagScale \u672c\u8eab\u6ca1\u6709\u786c\u4ef6\u5e73\u53f0\u8981\u6c42\u2014\u2014\u5b83\u901a\u8fc7 FlagOS \u63d2\u4ef6\u6765\u7f16\u6392\u8bad\u7ec3\u3002\u672c\u6307\u5357\u4ecb\u7ecd\u5982\u4f55\u5728\u56db\u7c7b\u975e NVIDIA \u5e73\u53f0\uff08\u6c90\u66e6\u3001\u6d77\u5149\u3001\u6607\u817e\u3001\u5e73\u5934\u54e5\uff09\u4e0a\uff0c\u914d\u5408\u5e95\u5c42\u63d2\u4ef6\u6808\u8dd1\u901a\u4e00\u6b21\u7aef\u5230\u7aef\u8bad\u7ec3\u3002</p><p>\u5404\u5e73\u53f0\u63d2\u4ef6\u7684\u5b89\u88c5\u65b9\u5f0f\u89c1\u63d2\u4ef6\u6587\u6863\uff1a</p>", "a[href=\"multi-platform-training.html#flagos\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. \u4f7f\u7528 FlagOS \u7b97\u5b50\u6808\u8fd0\u884c<a class=\"headerlink\" href=\"#flagos\" title=\"Link to this heading\">#</a></h2><p>\u82e5\u8981\u628a\u540c\u4e00\u4e2a\u4efb\u52a1\u6539\u5230 FlagTree + FlagGems \u4e0a\u8fd0\u884c\uff08\u800c\u975e\u5382\u5546\u7b97\u5b50\u5e93\uff09\uff0c\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">te_fl</span></code> \u914d\u7f6e\u5bf9\u5e76\u9009\u62e9 FlagOS \u5c42\uff1a</p>", "a[href=\"#id5\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u8bad\u7ec3<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h3><p>\u9700\u8981 Megatron-LM-FL \u73af\u5883</p>", "a[href=\"#id8\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u5f3a\u5316\u5b66\u4e60<a class=\"headerlink\" href=\"#id8\" title=\"Link to this heading\">#</a></h3><p>\u9700\u8981 verl-FL \u73af\u5883</p>", "a[href=\"#id6\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u63a8\u7406<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h3><p>\u9700\u8981 vLLM-FL \u73af\u5883</p>", "a[href=\"multi-platform-training.html#id9\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. \u6ce8\u610f\u4e8b\u9879<a class=\"headerlink\" href=\"#id9\" title=\"Link to this heading\">#</a></h2>", "a[href=\"multi-platform-training.html#id8\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. \u5df2\u77e5\u95ee\u9898\u4e0e\u89c4\u907f\u65b9\u5f0f<a class=\"headerlink\" href=\"#id8\" title=\"Link to this heading\">#</a></h2><h3>7.1 \u6c90\u66e6 MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">ImportError:</span> <span class=\"pre\">cannot</span> <span class=\"pre\">import</span> <span class=\"pre\">name</span> <span class=\"pre\">'AttrsDescriptor'</span> <span class=\"pre\">from</span> <span class=\"pre\">'triton.compiler.compiler'</span></code></strong> \u2014\u2014 \u5207\u6362\u5230 FlagTree \u540e\uff0cPyTorch \u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._inductor</span></code> \u627e\u4e0d\u5230 <code class=\"docutils literal notranslate\"><span class=\"pre\">AttrsDescriptor</span></code>\u3002\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">/opt/conda/lib/python3.12/site-packages/triton/compiler/compiler.py</span></code> \u4e2d\u8865\u5145\u517c\u5bb9\u5b9a\u4e49\uff1a</p>", "a[href=\"#id3\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u4efb\u52a1\u7ea7 YAML<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h3><p>\u4ee5 <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/qwen3/conf/serve/8b.yaml</span></code> \u4e3a\u4f8b\u8bf4\u660e\u6b64\u914d\u7f6e\u6587\u4ef6\u3002</p><p>\u4efb\u52a1\u7ea7 YAML \u6587\u4ef6\u6307\u5b9a\u6a21\u578b\u3001\u6570\u636e\u96c6\u4ee5\u53ca\u8bad\u7ec3\u6216\u63a8\u7406\u7b49\u5177\u4f53\u4efb\u52a1\u7684\u53c2\u6570\u3002\u6b64\u6587\u4ef6\u4e2d\u7684\u6bcf\u4e2a\u53c2\u6570\u90fd\u76f4\u63a5\u6620\u5c04\u5230\u540e\u7aef\u5f15\u64ce\u63a5\u53d7\u7684\u53c2\u6570\uff0c\u5176\u4e2d\u8fde\u5b57\u7b26\uff08-\uff09\u66ff\u6362\u4e3a\u4e0b\u5212\u7ebf\uff08\\_\uff09\u3002</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7b2c\u4e8c\u6b65\uff1a\u8fd0\u884c\u4efb\u52a1<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>FlagScale \u4e3a\u5404\u79cd\u4efb\u52a1\u63d0\u4f9b\u7edf\u4e00\u7684\u8fd0\u884c\u5668\uff0c\u5305\u62ec\u8bad\u7ec3\u3001\u63a8\u7406\u3001\u5f3a\u5316\u5b66\u4e60\u548c\u670d\u52a1\u3002\u53ea\u9700\u6307\u5b9a\u914d\u7f6e\u6587\u4ef6\uff0c\u5373\u53ef\u901a\u8fc7\u4e00\u6761 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagscale</span></code> \u547d\u4ee4\u8fd0\u884c\u4efb\u52a1\u3002\u8fd0\u884c\u5668\u4f1a\u81ea\u52a8\u52a0\u8f7d\u914d\u7f6e\u5e76\u6267\u884c\u4efb\u52a1\u3002\u4ee5\u4e0b\u5404\u8282\u6f14\u793a\u5982\u4f55\u8fd0\u884c\u5206\u5e03\u5f0f\u8bad\u7ec3\u4efb\u52a1\u3002</p>", "a[href=\"multi-platform-training.html#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. \u5e73\u53f0\u73af\u5883\u53d8\u91cf<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>FlagScale \u901a\u8fc7\u5b9e\u9a8c\u7ea7 YAML \u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">envs</span></code> \u6bb5\u4f20\u9012\u8bbe\u5907\u53ef\u89c1\u6027\uff0c\u5404\u5e73\u53f0\u7684\u53d8\u91cf\u540d\u4e0d\u540c\u3002</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b9e\u9a8c\u7ea7 YAML<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3><p>\u4ee5 <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/qwen3/conf/serve.yaml</span></code> \u4e3a\u4f8b\u8bf4\u660e\u6b64\u914d\u7f6e\u6587\u4ef6\u3002</p><p>\u5b9e\u9a8c\u7ea7\u6587\u4ef6\u662f <code class=\"docutils literal notranslate\"><span class=\"pre\">flagscale</span></code> \u547d\u4ee4\u7684\u5165\u53e3\u3002\u5b83\u5b9a\u4e49\u4e86\u8fd0\u884c\u7684\u5168\u5c40\u4e0a\u4e0b\u6587\uff1a</p>", "a[href=\"multi-platform-training.html#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. \u8fd0\u884c\u8bad\u7ec3\u6d4b\u8bd5<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h2><p>\u5728\u53e6\u4e00\u4e2a\u7ec8\u7aef\u89c2\u5bdf\u5361\u5360\u7528\u60c5\u51b5\uff1a</p>", "a[href=\"multi-platform-training.html#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. \u4f7f\u7528\u7684\u7ec4\u4ef6\u7248\u672c<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2>", "a[href=\"multi-platform-training.html#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. \u914d\u7f6e\u8bad\u7ec3\u4efb\u52a1<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><h3>4.1 \u5b9e\u9a8c\u7ea7 YAML<a class=\"headerlink\" href=\"#yaml\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">examples/qwen3/conf/train.yaml</span></code> \u7528\u4e8e\u9009\u62e9\u4efb\u52a1\u7ea7\u914d\u7f6e\u5e76\u5b9a\u4e49 runner \u73af\u5883\uff1a</p>", "a[href=\"#yaml\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7b2c\u4e00\u6b65\uff1a\u914d\u7f6e YAML \u6587\u4ef6<a class=\"headerlink\" href=\"#yaml\" title=\"Link to this heading\">#</a></h2><p>FlagScale \u4f7f\u7528 <a class=\"reference external\" href=\"https://hydra.cc/\">Hydra</a> \u8fdb\u884c\u914d\u7f6e\u7ba1\u7406\u3002\u6bcf\u4e2a\u4efb\u52a1\u7531\u4e24\u4e2a\u534f\u540c\u5de5\u4f5c\u7684 YAML \u6587\u4ef6\u9a71\u52a8\uff1a\u4e00\u4e2a\u5b9e\u9a8c\u7ea7\u6587\u4ef6\u548c\u4e00\u4e2a\u4efb\u52a1\u7ea7\u6587\u4ef6\uff0c\u5747\u4f4d\u4e8e <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/</span></code> \u76ee\u5f55\u4e0b\u3002\u8fd0\u884c\u4efb\u52a1\u524d\uff0c\u9700\u8981\u5148\u914d\u7f6e\u8fd9\u4e9b\u6587\u4ef6\u3002</p>", "a[href=\"multi-platform-training.html#flagscale\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. \u5b89\u88c5 FlagScale<a class=\"headerlink\" href=\"#flagscale\" title=\"Link to this heading\">#</a></h2><p>\u786e\u8ba4\u7248\u672c\uff0c\u5e76\u5b89\u88c5\u8bad\u7ec3\u6240\u9700\u7684\u65e5\u5fd7\u4f9d\u8d56\uff1a</p>"}
